  // Return the max money robbable with no two adjacent houses.
  return 0;
}

solution:
function Rob(nums: int[]) -> int {
  let prev = 0;
  let cur = 0;
  let i = 0;
  let n = nums.length();
  while (i < n) {
    let take = prev + nums[i];
    let next = take;
    if (cur > take) {
      next = cur;
    }
    prev = cur;
    cur = next;
    i += 1;
  }
  return cur;
}
